"""Merge per-row incoming findings into the single findings register (planning orchestrator, single writer).

Deterministic and idempotent: base rows are A2's F-01..F-44 (origin_ref empty or "A2"); every incoming file under
findings/incoming/ except A1.csv (already registered by A2 as F-40..F-43) is appended in sorted file order, rows in file
order, with fresh ids from F-045. Orchestrator severity rulings recorded in META_PLAN §11 are applied here and noted.
Also renders findings/REGISTER.md (counts + every S0/S1). Run: python3 tools/merge_findings.py
"""

from __future__ import annotations

import csv
import pathlib
from collections import Counter

PD = pathlib.Path(__file__).resolve().parents[1]
REG = PD / "findings" / "FINDINGS.csv"
INCOMING = PD / "findings" / "incoming"
OUT_MD = PD / "findings" / "REGISTER.md"
COLS = ["f_id", "title", "stream", "surface", "observed_at", "evidence_class", "evidence", "severity",
        "category", "spec_ids", "status", "routed_to", "operator_priority", "origin_ref"]
SKIP = {"A1.csv"}  # registered by A2 as F-40..F-43
# (origin_ref -> (severity, note)) orchestrator rulings, see META_PLAN §11
RULINGS = {"J1:NEW-2": ("S0", "orchestrator ruling: false public attribution claim live (META_PLAN §11)")}
SEV_ORDER = {"S0": 0, "S1": 1, "S2": 2, "S3": 3}


def load_base() -> list[dict]:
    rows = list(csv.DictReader(REG.open(newline="")))
    base = [r for r in rows if r.get("origin_ref", "") in ("", "A2")]
    for r in base:
        r["origin_ref"] = "A2"
    return base


def merged() -> list[dict]:
    rows = load_base()
    n = 45
    for f in sorted(INCOMING.glob("*.csv")):
        if f.name in SKIP:
            continue
        row_id = f.stem
        for r in csv.DictReader(f.open(newline="")):
            ref = f"{row_id}:{r.get('f_id', '').strip() or '?'}"
            out = {c: (r.get(c) or "").strip() for c in COLS}
            out["f_id"] = f"F-{n:03d}"
            out["origin_ref"] = ref
            if ref in RULINGS:
                sev, note = RULINGS[ref]
                out["severity"] = sev
                out["evidence"] = (out["evidence"] + " | " + note).strip(" |")
            rows.append(out)
            n += 1
    return rows


def render(rows: list[dict]) -> str:
    sev = Counter(r["severity"] or "?" for r in rows)
    src = Counter((r["origin_ref"] or "?").split(":")[0] for r in rows)
    lines = ["# Findings register (merged)", "",
             "Generated by `tools/merge_findings.py` from `FINDINGS.csv` (A2 base) + `incoming/*.csv`. Do not edit by hand.",
             "Per-row detail lives in each row's note; A2's `FINDINGS.md` keeps the verified F-01…F-44 narrative.", "",
             f"**Total:** {len(rows)} · " + " · ".join(f"{k} {sev[k]}" for k in sorted(sev, key=lambda s: SEV_ORDER.get(s, 9))), "",
             "**By originating row:** " + " · ".join(f"{k} {v}" for k, v in sorted(src.items())), "",
             "## S0 and S1", "", "| f_id | sev | origin | title | routed_to |", "|---|---|---|---|---|"]
    for r in sorted(rows, key=lambda r: (SEV_ORDER.get(r["severity"], 9), r["f_id"])):
        if r["severity"] in ("S0", "S1"):
            t = r["title"].replace("|", "/")
            lines.append(f"| {r['f_id']} | {r['severity']} | {r['origin_ref']} | {t} | {r['routed_to']} |")
    return "\n".join(lines) + "\n"


def main() -> None:
    rows = merged()
    with REG.open("w", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=COLS)
        w.writeheader()
        w.writerows(rows)
    OUT_MD.write_text(render(rows))
    print(f"{len(rows)} findings -> {REG.relative_to(PD)}; register -> {OUT_MD.relative_to(PD)}")


if __name__ == "__main__":
    main()
